package app.repositories

import app.common.Page
import app.entities.AuditEntry

/** Keeps audit_entries rows in memory, for tests and for trying the services without a database. */
class MemoryAuditEntryRepository : AuditEntryRepository {
    private val rows = linkedMapOf<List<Any?>, AuditEntry>()
    private var nextId = 1L

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: AuditEntry): List<Any?> = listOf(row.entryNo)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<AuditEntry> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findByEntryNo(entryNo: Int): AuditEntry? {
        return visible().firstOrNull { it.entryNo == entryNo }
    }

    override fun list(offset: Int, limit: Int): Page<AuditEntry> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun listByOrderId(orderId: Long): List<AuditEntry> {
        return visible().filter { it.orderId == orderId }
    }

    override fun insert(entity: AuditEntry): AuditEntry {
        entity.entryNo = entity.entryNo ?: (nextId++).toInt()
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: AuditEntry): AuditEntry {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: AuditEntry): Unit {
        rows.remove(keyOf(entity))
    }
}

