package app.repositories

import app.common.Page
import app.entities.AuditEntry
import app.entities.AuditEntryTable
import app.errors.ConflictException
import org.jetbrains.exposed.v1.core.ResultRow
import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.exceptions.ExposedSQLException
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.deleteWhere
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction
import org.jetbrains.exposed.v1.jdbc.update

/** Keeps audit_entries rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlAuditEntryRepository(private val db: Database) : AuditEntryRepository {
    override fun findByEntryNo(entryNo: Int): AuditEntry? {
        return exposedTransaction(db) {
            AuditEntryTable.selectAll().where { AuditEntryTable.entryNo eq entryNo }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<AuditEntry> {
        return exposedTransaction(db) {
            val query = AuditEntryTable.selectAll()
            val total = query.count()
            val items = query.orderBy(AuditEntryTable.entryNo to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun listByOrderId(orderId: Long): List<AuditEntry> {
        return exposedTransaction(db) {
            AuditEntryTable.selectAll().where { AuditEntryTable.orderId eq orderId }.orderBy(AuditEntryTable.entryNo to SortOrder.ASC).map { toEntity(it) }
        }
    }

    override fun insert(entity: AuditEntry): AuditEntry {
        return write {
            val statement = AuditEntryTable.insert { row ->
                entity.orderId?.let { row[AuditEntryTable.orderId] = it }
                entity.message?.let { row[AuditEntryTable.message] = it }
            }
            entity.entryNo = statement[AuditEntryTable.entryNo]
            fill(entity, AuditEntryTable.selectAll().where { AuditEntryTable.entryNo eq entity.entryNo!! }.single())
            entity
        }
    }

    override fun update(entity: AuditEntry): AuditEntry {
        return write {
            AuditEntryTable.update({ AuditEntryTable.entryNo eq entity.entryNo!! }) { row ->
                entity.orderId?.let { row[AuditEntryTable.orderId] = it }
                entity.message?.let { row[AuditEntryTable.message] = it }
            }
            entity
        }
    }

    override fun delete(entity: AuditEntry): Unit {
        write {
            AuditEntryTable.deleteWhere { AuditEntryTable.entryNo eq entity.entryNo!! }
        }
    }

    private fun toEntity(row: ResultRow): AuditEntry = AuditEntry().also { fill(it, row) }

    private fun fill(entity: AuditEntry, row: ResultRow) {
        entity.entryNo = row[AuditEntryTable.entryNo]
        entity.orderId = row[AuditEntryTable.orderId]
        entity.message = row[AuditEntryTable.message]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("AuditEntry", "the database refused the change: ${error.cause?.message}")
        }
}

