            val total = query.count()
            val items = query.orderBy(EmptyTable.id to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun insert(entity: Empty): Empty {
        return write {
            val statement = EmptyTable.insert { row ->
                entity.note?.let { row[EmptyTable.note] = it }
            }
            entity.id = statement[EmptyTable.id]
            fill(entity, EmptyTable.selectAll().where { EmptyTable.id eq entity.id!! }.single())
