package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.AuditEntry
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on audit_entries. Each write runs in its own transaction. */
class AuditEntryService(private val unitOfWork: UnitOfWork) {
    /** Stores a new AuditEntry after checking it. */
    fun createAuditEntry(auditEntry: AuditEntry): AuditEntry {
        val values = mapOf(
            "orderId" to auditEntry.orderId,
            "message" to auditEntry.message,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.auditEntries.insert(auditEntry)
        }
    }

    /** The AuditEntry with this key; NotFoundException when there is none. */
    fun getAuditEntry(entryNo: Int): AuditEntry = find(unitOfWork, entryNo)

    /** A page of audit_entries, by primary key. */
    fun listAuditEntries(offset: Int, limit: Int): Page<AuditEntry> = unitOfWork.auditEntries.list(offset, limit)

    /** Changes the given values of a AuditEntry. */
    fun updateAuditEntry(entryNo: Int, changes: AuditEntryChanges): AuditEntry {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, entryNo)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.auditEntries.update(current)
        }
    }

    /** Deletes a AuditEntry. */
    fun deleteAuditEntry(entryNo: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, entryNo)
            uow.auditEntries.delete(current)
        }
    }

    /** The audit_entries with this orderId. */
    fun listAuditEntriesByOrderId(orderId: Long): List<AuditEntry> = unitOfWork.auditEntries.listByOrderId(orderId)

    /** Checks the values against the rules of the "audit_entries" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: AuditEntry?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["orderId"]
            if (value == null) {
                if (creating || "orderId" in values) errors += FieldError("orderId", "is required")
            }
        }
        run {
            val value = values["message"]
            if (value == null) {
                if (creating || "message" in values) errors += FieldError("message", "is required")
            } else {
                if (value is String && value.length > 200) errors += FieldError("message", "is longer than 200 characters")
            }
        }
        run {
            val orderId = if ("orderId" in values) values["orderId"] as Long? else current?.orderId
            if (orderId != null && uow.order.findById(orderId) == null)
                errors += FieldError("orderId", "no Order has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("AuditEntry", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: AuditEntry?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: AuditEntry, values: Map<String, Any?>) {
        if ("orderId" in values) entity.orderId = values["orderId"] as Long?
        if ("message" in values) entity.message = values["message"] as String?
    }

    /** The AuditEntry with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, entryNo: Int): AuditEntry =
        uow.auditEntries.findByEntryNo(entryNo) ?: throw NotFoundException("AuditEntry", entryNo)

    /** The values an update gives, by field. */
    private fun given(changes: AuditEntryChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.orderId.isPresent) values["orderId"] = changes.orderId.value
        if (changes.message.isPresent) values["message"] = changes.message.value
        return values
    }
}

