package app

import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/** The repository of the "audit_entries" table, against the test database. */
class AuditEntryRepositoryTest {
    /** The repositories over the test database, opened empty for every test */
    private lateinit var uow: SqlUnitOfWork

    @BeforeTest
    fun open() {
        uow = TestDatabase.open()
    }

    @Test
    fun isStoredAndReadBack() {
        val stored = Factories.addAuditEntry(uow, 1)
        val found = uow.auditEntries.findByEntryNo(stored.entryNo!!)
        assertNotNull(found)
        assertEquals(stored.entryNo, found.entryNo)
        assertEquals(1, uow.auditEntries.listByOrderId(stored.orderId!!).size)
    }

    @Test
    fun listsRowsByKey() {
        Factories.addAuditEntry(uow, 1)
        Factories.addAuditEntry(uow, 2)
        val page = uow.auditEntries.list(0, 1)
        assertEquals(2L, page.total)
        assertEquals(1, page.items.size)
    }

    @Test
    fun storesTheChanges() {
        val stored = Factories.addAuditEntry(uow, 1)
        stored.message = "changed"
        uow.auditEntries.update(stored)
        assertEquals("changed", uow.auditEntries.findByEntryNo(stored.entryNo!!)?.message)
    }

    @Test
    fun isDeleted() {
        val stored = Factories.addAuditEntry(uow, 1)
        uow.auditEntries.delete(stored)
        assertNull(uow.auditEntries.findByEntryNo(stored.entryNo!!))
    }
}

