package app

import app.entities.AuditEntry
import app.entities.Empty
import app.entities.Kind
import app.entities.Order
import app.entities.Thing
import java.math.BigDecimal
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.LocalTime

/** Rows for the tests: valid values for every column, and the rows they point to. */
object Factories {
    /** A valid Thing that is not stored yet; n makes its unique values differ. */
    fun newThing(n: Int): Thing =
        Thing(
            tiny = n.toShort(),
            small = n.toShort(),
            medium = n,
            num = n,
            big = n.toLong(),
            price = BigDecimal("${n % 10000}.50"),
            r = n + 0.5f,
            d = n + 0.5,
            flag = true,
            born = LocalDate.of(2026, 1, n % 28 + 1),
            opens = LocalTime.of(12, n % 60),
            at = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0),
            changed = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0),
            bin = ByteArray(50) { n.toByte() },
            blobby = byteArrayOf(n.toByte()),
            data = "{\"n\": $n}",
            feeling = "sad",
            code = (n % 100000).toString().padStart(5, '0'),
            note = "note-$n",
            longNote = "longnote-$n",
        )

    /** A stored Thing. */
    fun addThing(uow: UnitOfWork, n: Int): Thing {
        val entity = newThing(n)
        return uow.things.insert(entity)
    }

    /** A valid Kind that is not stored yet; n makes its unique values differ. */
    fun newKind(n: Int): Kind =
        Kind(
            code = "code-$n",
            day = LocalDate.of(2026, 1, n % 28 + 1),
            label = "label-$n",
        )

    /** A stored Kind. */
    fun addKind(uow: UnitOfWork, n: Int): Kind {
        val entity = newKind(n)
        return uow.kinds.insert(entity)
    }

    /** A valid Order that is not stored yet; n makes its unique values differ. */
    fun newOrder(n: Int): Order =
        Order(
            user = "user-$n",
            group = n,
            customerName = "customername-$n",
            `class` = "class-$n",
            metadata = "metadata-$n",
            date = LocalDate.of(2026, 1, n % 28 + 1),
            time = LocalTime.of(12, n % 60),
            text = "text-$n",
            list = "list-$n",
            str = "str-$n",
            int = n,
            dueDate = LocalDate.of(2026, 1, n % 28 + 1),
            closesAt = LocalTime.of(12, n % 60),
        )

    /** A stored Order. */
    fun addOrder(uow: UnitOfWork, n: Int): Order {
        val entity = newOrder(n)
        return uow.order.insert(entity)
    }

    /** A valid AuditEntry that is not stored yet; n makes its unique values differ. */
    fun newAuditEntry(n: Int): AuditEntry =
        AuditEntry(
            message = "message-$n",
        )

    /** A stored AuditEntry, with the rows it points to. */
    fun addAuditEntry(uow: UnitOfWork, n: Int): AuditEntry {
        val parent0 = addOrder(uow, n)
        val entity = newAuditEntry(n)
        entity.orderId = parent0.id
        return uow.auditEntries.insert(entity)
    }

    /** A valid Empty that is not stored yet; n makes its unique values differ. */
    fun newEmpty(n: Int): Empty =
        Empty(
            note = "note-$n",
        )

    /** A stored Empty. */
    fun addEmpty(uow: UnitOfWork, n: Int): Empty {
        val entity = newEmpty(n)
        return uow.empties.insert(entity)
    }
}

