package app

import app.entities.AuditEntryTable
import app.entities.EmptyTable
import app.entities.KindTable
import app.entities.OrderTable
import app.entities.ThingTable
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.SchemaUtils
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction

/** The test database: the MariaDB database TEST_DATABASE_URL names (with TEST_DATABASE_USER and TEST_DATABASE_PASSWORD), created from the table objects before every test. */
object TestDatabase {
    private val TABLES = arrayOf(ThingTable, KindTable, OrderTable, AuditEntryTable, EmptyTable)

    /** The repositories over the test database, with every table dropped and created again. */
    fun open(): SqlUnitOfWork {
        val url = System.getenv("TEST_DATABASE_URL")
        // The table objects are written for one kind of database: the tests cannot fall back to SQLite
        checkNotNull(url) { "The database tests need a disposable MariaDB database: set TEST_DATABASE_URL (it is emptied)" }
        val db = Database.connect(url, user = System.getenv("TEST_DATABASE_USER") ?: "", password = System.getenv("TEST_DATABASE_PASSWORD") ?: "")
        exposedTransaction(db) {
            SchemaUtils.drop(*TABLES)
            // MariaDB takes no NULL after a computed column, which Exposed writes
            SchemaUtils.createStatements(*TABLES).forEach { exec(it.replace(" STORED NULL", " STORED")) }
        }
        return SqlUnitOfWork(db)
    }
}

